INSERT INTO public.wo_exercises (id,name,locais,categoria,equipamento,is_active,created_by,photo_url,video_url,tecnica_info,tecnica_notas,ajustes_maquina,contextos_exercicio,objetivos_exercicio) VALUES ('20b3cf02-9dc4-5c72-87fa-2621f5e6c4aa','Abdução isométrica da anca deitado com elástico',ARRAY['Casa','Clínica','Ginásio']::text[],ARRAY['Membro Inferior']::text[],ARRAY['Elásticos']::text[],TRUE,'32a24abe-cd69-42d9-bf3a-3355f4f6e28c','https://gc.joaomorais.pt/assets/exercicios/trocanterite/2026-10-28/isometrico-deitado.png',NULL,'{"posicao_inicial": ["De costas num tapete ou cama firme, joelhos fletidos e pés apoiados à largura da bacia. Elástico em laço à volta das coxas, acima dos joelhos, com tensão ligeira e sem apertar a pele."], "execucao": ["Pressione suavemente as coxas para fora contra o elástico e mantenha os joelhos imóveis à largura da bacia.", "Mantenha durante o tempo prescrito, relaxe completamente e repita."], "pontos_chave": ["A bacia fica apoiada. Escolha resistência que permita manter a posição sem esforço excessivo.", "Alternativa ao isométrico sentado; não somar os dois por rotina.", "Faça apenas a dose e a amplitude prescritas. Pare perante dor aguda ou perda de controlo."], "erros_comuns": ["Aumentar a carga ou a amplitude sem conseguir manter o controlo.", "Prender a respiração ou continuar apesar de agravamento."], "dicas": ["Respire normalmente. Peça ensino da técnica e adapte o lado exercitado."]}'::jsonb,'Posição inicial
• De costas num tapete ou cama firme, joelhos fletidos e pés apoiados à largura da bacia. Elástico em laço à volta das coxas, acima dos joelhos, com tensão ligeira e sem apertar a pele.

Execução
• Pressione suavemente as coxas para fora contra o elástico e mantenha os joelhos imóveis à largura da bacia.
• Mantenha durante o tempo prescrito, relaxe completamente e repita.

Pontos-chave
• A bacia fica apoiada. Escolha resistência que permita manter a posição sem esforço excessivo.
• Alternativa ao isométrico sentado; não somar os dois por rotina.
• Faça apenas a dose e a amplitude prescritas. Pare perante dor aguda ou perda de controlo.

Erros comuns
• Aumentar a carga ou a amplitude sem conseguir manter o controlo.
• Prender a respiração ou continuar apesar de agravamento.

Dicas
• Respire normalmente. Peça ensino da técnica e adapte o lado exercitado.','[]'::jsonb,ARRAY['Reabilitação']::text[],ARRAY['Fortalecimento']::text[]);
INSERT INTO public.wo_exercises (id,name,locais,categoria,equipamento,is_active,created_by,photo_url,video_url,tecnica_info,tecnica_notas,ajustes_maquina,contextos_exercicio,objetivos_exercicio) VALUES ('7f4156ae-b6a0-5b2e-804a-4e041ecb6650','Abdução isométrica da anca sentado com elástico',ARRAY['Casa','Clínica','Ginásio']::text[],ARRAY['Membro Inferior']::text[],ARRAY['Elásticos']::text[],TRUE,'32a24abe-cd69-42d9-bf3a-3355f4f6e28c','https://gc.joaomorais.pt/assets/exercicios/trocanterite/2026-10-28/isometrico-sentado.png',NULL,'{"posicao_inicial": ["Sentado numa cadeira estável, pés e joelhos à largura da bacia. Elástico em laço acima dos joelhos, com tensão ligeira e sem apertar a pele."], "execucao": ["Pressione suavemente as coxas para fora, sem movimento dos joelhos.", "Mantenha o tronco confortável, respire e relaxe entre exposições."], "pontos_chave": ["Alternativa ao isométrico deitado, não um exercício adicional obrigatório.", "Faça apenas a dose e a amplitude prescritas. Pare perante dor aguda ou perda de controlo."], "erros_comuns": ["Aumentar a carga ou a amplitude sem conseguir manter o controlo.", "Prender a respiração ou continuar apesar de agravamento."], "dicas": ["Respire normalmente. Peça ensino da técnica e adapte o lado exercitado."]}'::jsonb,'Posição inicial
• Sentado numa cadeira estável, pés e joelhos à largura da bacia. Elástico em laço acima dos joelhos, com tensão ligeira e sem apertar a pele.

Execução
• Pressione suavemente as coxas para fora, sem movimento dos joelhos.
• Mantenha o tronco confortável, respire e relaxe entre exposições.

Pontos-chave
• Alternativa ao isométrico deitado, não um exercício adicional obrigatório.
• Faça apenas a dose e a amplitude prescritas. Pare perante dor aguda ou perda de controlo.

Erros comuns
• Aumentar a carga ou a amplitude sem conseguir manter o controlo.
• Prender a respiração ou continuar apesar de agravamento.

Dicas
• Respire normalmente. Peça ensino da técnica e adapte o lado exercitado.','[]'::jsonb,ARRAY['Reabilitação']::text[],ARRAY['Fortalecimento']::text[]);
INSERT INTO public.wo_exercises (id,name,locais,categoria,equipamento,is_active,created_by,photo_url,video_url,tecnica_info,tecnica_notas,ajustes_maquina,contextos_exercicio,objetivos_exercicio) VALUES ('1424fa17-5c85-59d3-b946-182ed113461e','Ponte glútea bilateral — carga inicial',ARRAY['Casa','Clínica','Ginásio']::text[],ARRAY['Membro Inferior']::text[],ARRAY['Peso Corporal']::text[],TRUE,'32a24abe-cd69-42d9-bf3a-3355f4f6e28c','https://gc.joaomorais.pt/assets/exercicios/trocanterite/2026-10-28/ponte-bilateral.png',NULL,'{"posicao_inicial": ["De costas num tapete, joelhos fletidos, pés apoiados à largura da bacia e braços ao lado do corpo."], "execucao": ["Empurre o chão com os dois pés e eleve a bacia apenas até à altura tolerada.", "Regresse lentamente, sem arquear excessivamente a região lombar."], "pontos_chave": ["Distribua o esforço pelos dois pés e não deixe os joelhos cair para dentro.", "Faça apenas a dose e a amplitude prescritas. Pare perante dor aguda ou perda de controlo."], "erros_comuns": ["Aumentar a carga ou a amplitude sem conseguir manter o controlo.", "Prender a respiração ou continuar apesar de agravamento."], "dicas": ["Respire normalmente. Peça ensino da técnica e adapte o lado exercitado."]}'::jsonb,'Posição inicial
• De costas num tapete, joelhos fletidos, pés apoiados à largura da bacia e braços ao lado do corpo.

Execução
• Empurre o chão com os dois pés e eleve a bacia apenas até à altura tolerada.
• Regresse lentamente, sem arquear excessivamente a região lombar.

Pontos-chave
• Distribua o esforço pelos dois pés e não deixe os joelhos cair para dentro.
• Faça apenas a dose e a amplitude prescritas. Pare perante dor aguda ou perda de controlo.

Erros comuns
• Aumentar a carga ou a amplitude sem conseguir manter o controlo.
• Prender a respiração ou continuar apesar de agravamento.

Dicas
• Respire normalmente. Peça ensino da técnica e adapte o lado exercitado.','[]'::jsonb,ARRAY['Reabilitação']::text[],ARRAY['Fortalecimento']::text[]);
INSERT INTO public.wo_exercises (id,name,locais,categoria,equipamento,is_active,created_by,photo_url,video_url,tecnica_info,tecnica_notas,ajustes_maquina,contextos_exercicio,objetivos_exercicio) VALUES ('2390babe-f755-5163-9135-b0baf70d1e5d','Sentar e levantar de cadeira alta — controlo da anca',ARRAY['Casa','Clínica','Ginásio']::text[],ARRAY['Membro Inferior']::text[],ARRAY['Peso Corporal']::text[],TRUE,'32a24abe-cd69-42d9-bf3a-3355f4f6e28c','https://gc.joaomorais.pt/assets/exercicios/trocanterite/2026-10-28/sentar-levantar.png',NULL,'{"posicao_inicial": ["Cadeira firme encostada à parede, com altura que permita levantar sem esforço excessivo. Pés apoiados à largura da bacia."], "execucao": ["Incline ligeiramente o tronco para a frente e levante-se sem impulso.", "Volte a sentar-se devagar, mantendo os joelhos na direção dos pés."], "pontos_chave": ["Use apoio dos braços se necessário; reduza-o apenas quando conseguir.", "Ajuste altura e amplitude ao conforto.", "Faça apenas a dose e a amplitude prescritas. Pare perante dor aguda ou perda de controlo."], "erros_comuns": ["Aumentar a carga ou a amplitude sem conseguir manter o controlo.", "Prender a respiração ou continuar apesar de agravamento."], "dicas": ["Respire normalmente. Peça ensino da técnica e adapte o lado exercitado."]}'::jsonb,'Posição inicial
• Cadeira firme encostada à parede, com altura que permita levantar sem esforço excessivo. Pés apoiados à largura da bacia.

Execução
• Incline ligeiramente o tronco para a frente e levante-se sem impulso.
• Volte a sentar-se devagar, mantendo os joelhos na direção dos pés.

Pontos-chave
• Use apoio dos braços se necessário; reduza-o apenas quando conseguir.
• Ajuste altura e amplitude ao conforto.
• Faça apenas a dose e a amplitude prescritas. Pare perante dor aguda ou perda de controlo.

Erros comuns
• Aumentar a carga ou a amplitude sem conseguir manter o controlo.
• Prender a respiração ou continuar apesar de agravamento.

Dicas
• Respire normalmente. Peça ensino da técnica e adapte o lado exercitado.','[]'::jsonb,ARRAY['Reabilitação']::text[],ARRAY['Fortalecimento']::text[]);
INSERT INTO public.wo_exercises (id,name,locais,categoria,equipamento,is_active,created_by,photo_url,video_url,tecnica_info,tecnica_notas,ajustes_maquina,contextos_exercicio,objetivos_exercicio) VALUES ('075634b8-38e8-5a60-9ca9-8c7dca2b77f3','Transferência lateral de peso com apoio das mãos',ARRAY['Casa','Clínica','Ginásio']::text[],ARRAY['Membro Inferior']::text[],ARRAY['Sem equipamento']::text[],TRUE,'32a24abe-cd69-42d9-bf3a-3355f4f6e28c','https://gc.joaomorais.pt/assets/exercicios/trocanterite/2026-10-28/transferencia-peso.png',NULL,'{"posicao_inicial": ["De pé diante de apoio estável, mãos apoiadas e ambos os pés no chão à largura da bacia."], "execucao": ["Desloque uma pequena parte do peso para uma perna, mantendo os dois pés apoiados.", "Regresse ao centro e alterne, sem deixar a bacia cair para o lado."], "pontos_chave": ["Movimento pequeno. Não ficar pendurado numa só anca.", "Reduza o deslocamento ou substitua a opção se provocar dor.", "Faça apenas a dose e a amplitude prescritas. Pare perante dor aguda ou perda de controlo."], "erros_comuns": ["Aumentar a carga ou a amplitude sem conseguir manter o controlo.", "Prender a respiração ou continuar apesar de agravamento."], "dicas": ["Respire normalmente. Peça ensino da técnica e adapte o lado exercitado."]}'::jsonb,'Posição inicial
• De pé diante de apoio estável, mãos apoiadas e ambos os pés no chão à largura da bacia.

Execução
• Desloque uma pequena parte do peso para uma perna, mantendo os dois pés apoiados.
• Regresse ao centro e alterne, sem deixar a bacia cair para o lado.

Pontos-chave
• Movimento pequeno. Não ficar pendurado numa só anca.
• Reduza o deslocamento ou substitua a opção se provocar dor.
• Faça apenas a dose e a amplitude prescritas. Pare perante dor aguda ou perda de controlo.

Erros comuns
• Aumentar a carga ou a amplitude sem conseguir manter o controlo.
• Prender a respiração ou continuar apesar de agravamento.

Dicas
• Respire normalmente. Peça ensino da técnica e adapte o lado exercitado.','[]'::jsonb,ARRAY['Reabilitação']::text[],ARRAY['Propriocepção / Equilíbrio']::text[]);
INSERT INTO public.wo_exercises (id,name,locais,categoria,equipamento,is_active,created_by,photo_url,video_url,tecnica_info,tecnica_notas,ajustes_maquina,contextos_exercicio,objetivos_exercicio) VALUES ('ece7242a-1df4-55ed-910a-e7b4caf32af6','Abdução da anca em pé sem resistência e com apoio',ARRAY['Casa','Clínica','Ginásio']::text[],ARRAY['Membro Inferior']::text[],ARRAY['Sem equipamento']::text[],TRUE,'32a24abe-cd69-42d9-bf3a-3355f4f6e28c','https://gc.joaomorais.pt/assets/exercicios/trocanterite/2026-10-28/abducao-sem-carga.png',NULL,'{"posicao_inicial": ["De pé junto a uma cadeira firme, segurando o encosto. Tronco vertical, bacia nivelada e pés paralelos."], "execucao": ["Afaste ligeiramente a perna a exercitar para o lado, mantendo o pé para a frente.", "Regresse até à posição inicial, sem cruzar a linha do corpo."], "pontos_chave": ["Comece com amplitude pequena e sem elástico.", "O apoio na outra perna também exige esforço: se agravar os sintomas, escolha uma opção deitada ou sentada.", "Faça apenas a dose e a amplitude prescritas. Pare perante dor aguda ou perda de controlo."], "erros_comuns": ["Aumentar a carga ou a amplitude sem conseguir manter o controlo.", "Prender a respiração ou continuar apesar de agravamento."], "dicas": ["Respire normalmente. Peça ensino da técnica e adapte o lado exercitado."]}'::jsonb,'Posição inicial
• De pé junto a uma cadeira firme, segurando o encosto. Tronco vertical, bacia nivelada e pés paralelos.

Execução
• Afaste ligeiramente a perna a exercitar para o lado, mantendo o pé para a frente.
• Regresse até à posição inicial, sem cruzar a linha do corpo.

Pontos-chave
• Comece com amplitude pequena e sem elástico.
• O apoio na outra perna também exige esforço: se agravar os sintomas, escolha uma opção deitada ou sentada.
• Faça apenas a dose e a amplitude prescritas. Pare perante dor aguda ou perda de controlo.

Erros comuns
• Aumentar a carga ou a amplitude sem conseguir manter o controlo.
• Prender a respiração ou continuar apesar de agravamento.

Dicas
• Respire normalmente. Peça ensino da técnica e adapte o lado exercitado.','[]'::jsonb,ARRAY['Reabilitação']::text[],ARRAY['Fortalecimento']::text[]);
INSERT INTO public.wo_exercises (id,name,locais,categoria,equipamento,is_active,created_by,photo_url,video_url,tecnica_info,tecnica_notas,ajustes_maquina,contextos_exercicio,objetivos_exercicio) VALUES ('1ba475e5-d6b1-574f-af42-0e8af5e480ef','Subida de degrau baixo com apoio — controlo da anca',ARRAY['Casa','Clínica','Ginásio']::text[],ARRAY['Membro Inferior']::text[],ARRAY['Peso Corporal']::text[],TRUE,'32a24abe-cd69-42d9-bf3a-3355f4f6e28c','https://gc.joaomorais.pt/assets/exercicios/trocanterite/2026-10-28/step-up.png',NULL,'{"posicao_inicial": ["Diante de um degrau baixo, firme e antiderrapante, com corrimão ao lado. Pé da perna a exercitar totalmente apoiado no degrau."], "execucao": ["Suba com controlo, sem impulso excessivo da perna de trás.", "Desça devagar e repita na altura e amplitude prescritas."], "pontos_chave": ["Mantenha o joelho orientado com o pé e a bacia controlada.", "Use o corrimão. Não existe uma altura obrigatória; não use bancos instáveis.", "Faça apenas a dose e a amplitude prescritas. Pare perante dor aguda ou perda de controlo."], "erros_comuns": ["Aumentar a carga ou a amplitude sem conseguir manter o controlo.", "Prender a respiração ou continuar apesar de agravamento."], "dicas": ["Respire normalmente. Peça ensino da técnica e adapte o lado exercitado."]}'::jsonb,'Posição inicial
• Diante de um degrau baixo, firme e antiderrapante, com corrimão ao lado. Pé da perna a exercitar totalmente apoiado no degrau.

Execução
• Suba com controlo, sem impulso excessivo da perna de trás.
• Desça devagar e repita na altura e amplitude prescritas.

Pontos-chave
• Mantenha o joelho orientado com o pé e a bacia controlada.
• Use o corrimão. Não existe uma altura obrigatória; não use bancos instáveis.
• Faça apenas a dose e a amplitude prescritas. Pare perante dor aguda ou perda de controlo.

Erros comuns
• Aumentar a carga ou a amplitude sem conseguir manter o controlo.
• Prender a respiração ou continuar apesar de agravamento.

Dicas
• Respire normalmente. Peça ensino da técnica e adapte o lado exercitado.','[]'::jsonb,ARRAY['Reabilitação']::text[],ARRAY['Fortalecimento']::text[]);
INSERT INTO public.wo_exercises (id,name,locais,categoria,equipamento,is_active,created_by,photo_url,video_url,tecnica_info,tecnica_notas,ajustes_maquina,contextos_exercicio,objetivos_exercicio) VALUES ('95a11dd8-7181-5aad-871c-49d73c318084','Apoio numa perna com apoio da mão — controlo da bacia',ARRAY['Casa','Clínica','Ginásio']::text[],ARRAY['Membro Inferior']::text[],ARRAY['Sem equipamento']::text[],TRUE,'32a24abe-cd69-42d9-bf3a-3355f4f6e28c','https://gc.joaomorais.pt/assets/exercicios/trocanterite/2026-10-28/apoio-unipodal.png',NULL,'{"posicao_inicial": ["De pé ao lado de uma cadeira firme, em chão plano e com olhos abertos. Uma mão apoiada no encosto."], "execucao": ["Transfira o peso para a perna a exercitar e eleve ligeiramente o outro pé.", "Mantenha a bacia nivelada pelo tempo prescrito. Volte aos dois apoios e descanse."], "pontos_chave": ["Ajuste o apoio da mão e o tempo à tolerância. Não deixe a bacia cair.", "Não progrida automaticamente para olhos fechados ou superfície instável.", "Faça apenas a dose e a amplitude prescritas. Pare perante dor aguda ou perda de controlo."], "erros_comuns": ["Aumentar a carga ou a amplitude sem conseguir manter o controlo.", "Prender a respiração ou continuar apesar de agravamento."], "dicas": ["Respire normalmente. Peça ensino da técnica e adapte o lado exercitado."]}'::jsonb,'Posição inicial
• De pé ao lado de uma cadeira firme, em chão plano e com olhos abertos. Uma mão apoiada no encosto.

Execução
• Transfira o peso para a perna a exercitar e eleve ligeiramente o outro pé.
• Mantenha a bacia nivelada pelo tempo prescrito. Volte aos dois apoios e descanse.

Pontos-chave
• Ajuste o apoio da mão e o tempo à tolerância. Não deixe a bacia cair.
• Não progrida automaticamente para olhos fechados ou superfície instável.
• Faça apenas a dose e a amplitude prescritas. Pare perante dor aguda ou perda de controlo.

Erros comuns
• Aumentar a carga ou a amplitude sem conseguir manter o controlo.
• Prender a respiração ou continuar apesar de agravamento.

Dicas
• Respire normalmente. Peça ensino da técnica e adapte o lado exercitado.','[]'::jsonb,ARRAY['Reabilitação']::text[],ARRAY['Propriocepção / Equilíbrio']::text[]);
INSERT INTO public.wo_exercises (id,name,locais,categoria,equipamento,is_active,created_by,photo_url,video_url,tecnica_info,tecnica_notas,ajustes_maquina,contextos_exercicio,objetivos_exercicio) VALUES ('ea23e3b3-321d-5897-a2a2-0e7b93daf680','Abdução da anca com elástico — tendinopatia glútea',ARRAY['Casa','Clínica','Ginásio']::text[],ARRAY['Membro Inferior']::text[],ARRAY['Elásticos']::text[],TRUE,'32a24abe-cd69-42d9-bf3a-3355f4f6e28c','https://nxfnzzcuqzxmzsihbrtp.supabase.co/storage/v1/object/public/wo-exercises/59eaa0f7-3ac0-4508-afb0-4513b5a8e547.jpg',NULL,'{"posicao_inicial": ["De pé com apoio estável disponível, elástico leve nos tornozelos e pés paralelos à largura da bacia."], "execucao": ["Afaste lateralmente a perna a exercitar na amplitude prescrita, sem inclinar o tronco.", "Regresse devagar até à largura inicial; não deixe a perna cruzar a linha do corpo."], "pontos_chave": ["A imagem demonstra a variante sem apoio; use apoio da mão se necessário.", "Aumente a resistência só mantendo controlo da bacia e boa tolerância.", "Faça apenas a dose e a amplitude prescritas. Pare perante dor aguda ou perda de controlo."], "erros_comuns": ["Aumentar a carga ou a amplitude sem conseguir manter o controlo.", "Prender a respiração ou continuar apesar de agravamento."], "dicas": ["Respire normalmente. Peça ensino da técnica e adapte o lado exercitado."]}'::jsonb,'Posição inicial
• De pé com apoio estável disponível, elástico leve nos tornozelos e pés paralelos à largura da bacia.

Execução
• Afaste lateralmente a perna a exercitar na amplitude prescrita, sem inclinar o tronco.
• Regresse devagar até à largura inicial; não deixe a perna cruzar a linha do corpo.

Pontos-chave
• A imagem demonstra a variante sem apoio; use apoio da mão se necessário.
• Aumente a resistência só mantendo controlo da bacia e boa tolerância.
• Faça apenas a dose e a amplitude prescritas. Pare perante dor aguda ou perda de controlo.

Erros comuns
• Aumentar a carga ou a amplitude sem conseguir manter o controlo.
• Prender a respiração ou continuar apesar de agravamento.

Dicas
• Respire normalmente. Peça ensino da técnica e adapte o lado exercitado.','[]'::jsonb,ARRAY['Reabilitação']::text[],ARRAY['Fortalecimento']::text[]);
INSERT INTO public.wo_exercises (id,name,locais,categoria,equipamento,is_active,created_by,photo_url,video_url,tecnica_info,tecnica_notas,ajustes_maquina,contextos_exercicio,objetivos_exercicio) VALUES ('8809542f-7cb6-5df9-9581-258873b3975b','Ponte unipodal — progressão funcional da anca',ARRAY['Casa','Clínica','Ginásio']::text[],ARRAY['Membro Inferior']::text[],ARRAY['Peso Corporal']::text[],TRUE,'32a24abe-cd69-42d9-bf3a-3355f4f6e28c','https://nxfnzzcuqzxmzsihbrtp.supabase.co/storage/v1/object/public/wo-exercises/7b507499-862b-4ae0-81cc-5dc82f60a834.jpg',NULL,'{"posicao_inicial": ["De costas, um pé apoiado e joelho fletido. Eleve a outra perna conforme ensino."], "execucao": ["Eleve a bacia pela perna de apoio, dentro da amplitude tolerada.", "Desça lentamente, sem rodar a bacia ou arquear a região lombar."], "pontos_chave": ["A perna livre pode ficar fletida para facilitar; a imagem ilustra uma variante mais exigente.", "Substitua pela ponte bilateral se perder controlo ou agravar.", "Faça apenas a dose e a amplitude prescritas. Pare perante dor aguda ou perda de controlo."], "erros_comuns": ["Aumentar a carga ou a amplitude sem conseguir manter o controlo.", "Prender a respiração ou continuar apesar de agravamento."], "dicas": ["Respire normalmente. Peça ensino da técnica e adapte o lado exercitado."]}'::jsonb,'Posição inicial
• De costas, um pé apoiado e joelho fletido. Eleve a outra perna conforme ensino.

Execução
• Eleve a bacia pela perna de apoio, dentro da amplitude tolerada.
• Desça lentamente, sem rodar a bacia ou arquear a região lombar.

Pontos-chave
• A perna livre pode ficar fletida para facilitar; a imagem ilustra uma variante mais exigente.
• Substitua pela ponte bilateral se perder controlo ou agravar.
• Faça apenas a dose e a amplitude prescritas. Pare perante dor aguda ou perda de controlo.

Erros comuns
• Aumentar a carga ou a amplitude sem conseguir manter o controlo.
• Prender a respiração ou continuar apesar de agravamento.

Dicas
• Respire normalmente. Peça ensino da técnica e adapte o lado exercitado.','[]'::jsonb,ARRAY['Reabilitação']::text[],ARRAY['Fortalecimento']::text[]);
INSERT INTO public.wo_exercises (id,name,locais,categoria,equipamento,is_active,created_by,photo_url,video_url,tecnica_info,tecnica_notas,ajustes_maquina,contextos_exercicio,objetivos_exercicio) VALUES ('44ded999-34a9-5225-9423-0211358b2431','Agachamento — progressão funcional da anca',ARRAY['Casa','Clínica','Ginásio']::text[],ARRAY['Membro Inferior']::text[],ARRAY['Peso Corporal']::text[],TRUE,'32a24abe-cd69-42d9-bf3a-3355f4f6e28c','https://nxfnzzcuqzxmzsihbrtp.supabase.co/storage/v1/object/public/wo-exercises/a0c045f3-2362-427f-92f0-07f86565611b.jpg',NULL,'{"posicao_inicial": ["De pé, pés numa largura confortável e apoio estável disponível. Começar sem carga externa."], "execucao": ["Fleta a anca e os joelhos dentro da amplitude prescrita, levando a bacia para trás.", "Volte a subir com controlo e pés apoiados."], "pontos_chave": ["Não precisa de atingir a profundidade ilustrada.", "Aumente amplitude ou resistência separadamente, conforme o objetivo.", "Faça apenas a dose e a amplitude prescritas. Pare perante dor aguda ou perda de controlo."], "erros_comuns": ["Aumentar a carga ou a amplitude sem conseguir manter o controlo.", "Prender a respiração ou continuar apesar de agravamento."], "dicas": ["Respire normalmente. Peça ensino da técnica e adapte o lado exercitado."]}'::jsonb,'Posição inicial
• De pé, pés numa largura confortável e apoio estável disponível. Começar sem carga externa.

Execução
• Fleta a anca e os joelhos dentro da amplitude prescrita, levando a bacia para trás.
• Volte a subir com controlo e pés apoiados.

Pontos-chave
• Não precisa de atingir a profundidade ilustrada.
• Aumente amplitude ou resistência separadamente, conforme o objetivo.
• Faça apenas a dose e a amplitude prescritas. Pare perante dor aguda ou perda de controlo.

Erros comuns
• Aumentar a carga ou a amplitude sem conseguir manter o controlo.
• Prender a respiração ou continuar apesar de agravamento.

Dicas
• Respire normalmente. Peça ensino da técnica e adapte o lado exercitado.','[]'::jsonb,ARRAY['Reabilitação']::text[],ARRAY['Fortalecimento']::text[]);
INSERT INTO public.wo_exercises (id,name,locais,categoria,equipamento,is_active,created_by,photo_url,video_url,tecnica_info,tecnica_notas,ajustes_maquina,contextos_exercicio,objetivos_exercicio) VALUES ('0bba9a10-6de5-5552-89bb-0d59714f148c','Descida lateral de degrau — controlo da anca',ARRAY['Casa','Clínica','Ginásio']::text[],ARRAY['Membro Inferior']::text[],ARRAY['Peso Corporal']::text[],TRUE,'32a24abe-cd69-42d9-bf3a-3355f4f6e28c','https://nxfnzzcuqzxmzsihbrtp.supabase.co/storage/v1/object/public/wo-exercises/6f229b7e-87bc-4345-befa-0ee146f5d098.jpg',NULL,'{"posicao_inicial": ["De pé sobre um degrau firme e baixo, junto a um corrimão, com uma perna livre ao lado."], "execucao": ["Fleta lentamente a anca e o joelho da perna de apoio, aproximando o calcanhar livre do chão.", "Volte a subir sem impulso da perna livre."], "pontos_chave": ["A imagem mostra uma plataforma alta; use apenas a altura individualmente prescrita.", "Joelho acompanha o pé; reduza altura e use apoio antes de aumentar a dificuldade.", "Faça apenas a dose e a amplitude prescritas. Pare perante dor aguda ou perda de controlo."], "erros_comuns": ["Aumentar a carga ou a amplitude sem conseguir manter o controlo.", "Prender a respiração ou continuar apesar de agravamento."], "dicas": ["Respire normalmente. Peça ensino da técnica e adapte o lado exercitado."]}'::jsonb,'Posição inicial
• De pé sobre um degrau firme e baixo, junto a um corrimão, com uma perna livre ao lado.

Execução
• Fleta lentamente a anca e o joelho da perna de apoio, aproximando o calcanhar livre do chão.
• Volte a subir sem impulso da perna livre.

Pontos-chave
• A imagem mostra uma plataforma alta; use apenas a altura individualmente prescrita.
• Joelho acompanha o pé; reduza altura e use apoio antes de aumentar a dificuldade.
• Faça apenas a dose e a amplitude prescritas. Pare perante dor aguda ou perda de controlo.

Erros comuns
• Aumentar a carga ou a amplitude sem conseguir manter o controlo.
• Prender a respiração ou continuar apesar de agravamento.

Dicas
• Respire normalmente. Peça ensino da técnica e adapte o lado exercitado.','[]'::jsonb,ARRAY['Reabilitação']::text[],ARRAY['Fortalecimento']::text[]);
INSERT INTO public.wo_exercises (id,name,locais,categoria,equipamento,is_active,created_by,photo_url,video_url,tecnica_info,tecnica_notas,ajustes_maquina,contextos_exercicio,objetivos_exercicio) VALUES ('58395a75-d012-5133-9056-a5480e093009','Dobradiça da anca com halteres — progressão funcional',ARRAY['Casa','Clínica','Ginásio']::text[],ARRAY['Membro Inferior']::text[],ARRAY['Halteres']::text[],TRUE,'32a24abe-cd69-42d9-bf3a-3355f4f6e28c','https://nxfnzzcuqzxmzsihbrtp.supabase.co/storage/v1/object/public/wo-exercises/24670ab3-ed78-41b6-a50d-19174578f1f7.jpg',NULL,'{"posicao_inicial": ["De pé, pés à largura da bacia e joelhos ligeiramente fletidos. Halteres leves apenas se prescritos."], "execucao": ["Leve a bacia para trás, inclinando o tronco como um conjunto e mantendo os pesos próximos das pernas.", "Volte à posição vertical com controlo, sem empurrar a bacia excessivamente para a frente."], "pontos_chave": ["É um complemento funcional, não um exercício isolado dos tendões glúteos.", "A amplitude depende da capacidade de manter controlo; não procure tocar no chão.", "Faça apenas a dose e a amplitude prescritas. Pare perante dor aguda ou perda de controlo."], "erros_comuns": ["Aumentar a carga ou a amplitude sem conseguir manter o controlo.", "Prender a respiração ou continuar apesar de agravamento."], "dicas": ["Respire normalmente. Peça ensino da técnica e adapte o lado exercitado."]}'::jsonb,'Posição inicial
• De pé, pés à largura da bacia e joelhos ligeiramente fletidos. Halteres leves apenas se prescritos.

Execução
• Leve a bacia para trás, inclinando o tronco como um conjunto e mantendo os pesos próximos das pernas.
• Volte à posição vertical com controlo, sem empurrar a bacia excessivamente para a frente.

Pontos-chave
• É um complemento funcional, não um exercício isolado dos tendões glúteos.
• A amplitude depende da capacidade de manter controlo; não procure tocar no chão.
• Faça apenas a dose e a amplitude prescritas. Pare perante dor aguda ou perda de controlo.

Erros comuns
• Aumentar a carga ou a amplitude sem conseguir manter o controlo.
• Prender a respiração ou continuar apesar de agravamento.

Dicas
• Respire normalmente. Peça ensino da técnica e adapte o lado exercitado.','[]'::jsonb,ARRAY['Reabilitação']::text[],ARRAY['Fortalecimento']::text[]);
INSERT INTO public.wo_exercises (id,name,locais,categoria,equipamento,is_active,created_by,photo_url,video_url,tecnica_info,tecnica_notas,ajustes_maquina,contextos_exercicio,objetivos_exercicio) VALUES ('f9ecc876-b099-59e8-a24c-9b05142042dd','Passos laterais com elástico — controlo da anca',ARRAY['Casa','Clínica','Ginásio']::text[],ARRAY['Membro Inferior']::text[],ARRAY['Elásticos']::text[],TRUE,'32a24abe-cd69-42d9-bf3a-3355f4f6e28c','https://nxfnzzcuqzxmzsihbrtp.supabase.co/storage/v1/object/public/wo-exercises/20ed9268-69fd-4913-8e6f-fc0d5e674671.jpg',NULL,'{"posicao_inicial": ["De pé com elástico leve nos tornozelos, pés paralelos e ligeira flexão confortável dos joelhos. Apoio próximo se necessário."], "execucao": ["Dê um passo lateral curto, mantendo a bacia controlada.", "Aproxime a outra perna apenas até à largura inicial; não cruze nem junte completamente os pés.", "Faça os passos prescritos e regresse na direção oposta."], "pontos_chave": ["Use pouca tensão inicial. Não rode os pés ou balance o tronco para puxar o elástico.", "Não precisa de manter um agachamento profundo.", "Faça apenas a dose e a amplitude prescritas. Pare perante dor aguda ou perda de controlo."], "erros_comuns": ["Aumentar a carga ou a amplitude sem conseguir manter o controlo.", "Prender a respiração ou continuar apesar de agravamento."], "dicas": ["Respire normalmente. Peça ensino da técnica e adapte o lado exercitado."]}'::jsonb,'Posição inicial
• De pé com elástico leve nos tornozelos, pés paralelos e ligeira flexão confortável dos joelhos. Apoio próximo se necessário.

Execução
• Dê um passo lateral curto, mantendo a bacia controlada.
• Aproxime a outra perna apenas até à largura inicial; não cruze nem junte completamente os pés.
• Faça os passos prescritos e regresse na direção oposta.

Pontos-chave
• Use pouca tensão inicial. Não rode os pés ou balance o tronco para puxar o elástico.
• Não precisa de manter um agachamento profundo.
• Faça apenas a dose e a amplitude prescritas. Pare perante dor aguda ou perda de controlo.

Erros comuns
• Aumentar a carga ou a amplitude sem conseguir manter o controlo.
• Prender a respiração ou continuar apesar de agravamento.

Dicas
• Respire normalmente. Peça ensino da técnica e adapte o lado exercitado.','[]'::jsonb,ARRAY['Reabilitação']::text[],ARRAY['Fortalecimento']::text[]);
INSERT INTO public.protocols_catalog (id,region,name,kind,is_active,sort_order,data) VALUES ('411813db-6662-5598-af67-cfb2e38bc0f1','anca','Trocanterite — síndrome de dor do grande trocânter / tendinopatia glútea','conservador',TRUE,10,'{"version": 1, "versao_clinica": "2026-10-28", "contextos": ["Casa", "Clínica", "Ginásio"], "fontes": [{"title": "Mellor et al. 2018 — ensaio LEAP", "url": "https://www.bmj.com/content/361/bmj.k1662", "doi": "10.1136/bmj.k1662"}, {"title": "Mellor et al. 2016 — protocolo LEAP", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC4852446/", "doi": "10.1186/s12891-016-1043-6"}, {"title": "ISHA 2022, publicado em 2023 — consenso", "url": "https://pmc.ncbi.nlm.nih.gov/articles/PMC10234389/", "doi": "10.1093/jhps/hnac050"}, {"title": "Clifford et al. 2019 — ensaio piloto de isométricos e isotónicos", "url": "https://pubmed.ncbi.nlm.nih.gov/31673402/", "doi": "10.1136/bmjsem-2019-000558"}], "status_revisao": "revisto_com_limites_de_evidencia_2026-10-28", "nota_clinica": "Programa conservador para dor lateral da anca clinicamente compatível com tendinopatia glútea. Não é um protocolo pós-operatório nem de rotura aguda. Três fases por evolução clínica; seis opções por fase, com seleção individual.", "dose": "Pontos de partida práticos individualizáveis. O conjunto, as doses e os critérios de passagem não foram validados como protocolo único.", "auditoria_cientifica": {"data": "2026-10-28", "evidencia": "Educação e exercício apoiados por ensaio clínico; seleção e doses adaptadas para a biblioteca GC.", "limites": "O ensaio LEAP estudou dor persistente, não valida por si só a fase altamente irritável nem o retorno ao desporto.", "imagens": "Oito ilustrações novas e seis imagens existentes, sujeitas a inspeção visual antes da ativação."}}'::jsonb);
INSERT INTO public.protocol_phases (id,protocol_id,phase_order,name,anchor_kind,anchor_from,anchor_to,data) VALUES ('a70884fa-71d4-50d4-84b7-eec40824b092','411813db-6662-5598-af67-cfb2e38bc0f1',1,'Proteção relativa e carga inicial tolerada','evolucao_clinica',NULL,NULL,'{"nota_ancora": "Progressão por evolução clínica; sem semanas fixas. Doses iniciais ajustáveis pelo prescritor.", "objetivos": [{"id": "o1", "label": "Reduzir a irritabilidade e encontrar uma dose tolerada, sem repouso absoluto."}, {"id": "o2", "label": "Manter ativação e recuperar tarefas simples com apoio e controlo."}], "permitido": ["Carga tolerada e progressiva, dentro do plano individual.", "Uso de apoio estável e redução de amplitude quando necessários."], "contraindicacoes": ["Não forçar alongamentos que cruzem a perna sobre o corpo enquanto provocarem dor lateral da anca.", "Evitar progressões bruscas, repetir testes dolorosos ou treinar com claudicação.", "Este plano não substitui restrições específicas após cirurgia, traumatismo, suspeita de fratura ou rotura aguda."], "hep": ["As seis opções não são obrigatórias. Fazer apenas a seleção e a dose prescritas.", "As doses do catálogo são pontos de partida práticos e devem ser revistas conforme resposta."], "recomendacoes": [{"title": "O seu plano", "text": "Faça apenas os exercícios selecionados para si. Nesta fase, começar habitualmente com 2–3 opções. Os dois isométricos são alternativas: escolha um, sem os somar por rotina."}, {"title": "Sono e posições", "text": "Enquanto houver dor, evite apoiar diretamente a anca dolorosa. Experimente dormir de costas ou sobre o lado mais confortável, com almofada entre as coxas e os joelhos, mantendo a perna de cima apoiada."}, {"title": "Atividades diárias", "text": "Reduza temporariamente posições que provoquem dor: pernas cruzadas ou ficar apoiado numa só anca com a bacia caída. Distribua o peso pelos dois pés e sente-se para vestir calças, se necessário. Ajuste a altura da cadeira apenas se ajudar."}, {"title": "Caminhar e manter atividade", "text": "Divida a caminhada em períodos curtos e em plano, conforme tolerância. Reduza temporariamente escadas, ladeiras e passos longos se agravarem. Não existe uma duração mínima obrigatória. A bicicleta ou a natação só entram se forem bem toleradas."}, {"title": "Frequência", "text": "Ativação ligeira pode ser feita numa sessão curta por dia, se tolerada. Na ponte e no sentar/levantar, começar em dias alternados. Não junte todas as opções nem repita sessões para compensar um dia falhado."}, {"title": "Resposta ao exercício", "text": "Faça os movimentos com desconforto ligeiro e tolerável. Como referência inicial, procure não ultrapassar 3/10, salvo indicação individual. Reduza ou interrompa se a dor aumentar, alterar a marcha ou a técnica. A dor deve aproximar-se do habitual após a sessão, sem piorar claramente o sono ou a manhã seguinte; se continuar agravada no dia seguinte, reduza a dose e contacte a equipa."}, {"title": "Quando pedir ajuda", "text": "Procure avaliação urgente se não conseguir apoiar a perna após queda, surgir dor súbita intensa, febre com anca quente ou inchada, ou fraqueza/dormência novas. Peça reavaliação se a dor piorar de forma persistente, surgir dor profunda na virilha, ou não houver evolução apesar do plano ajustado."}], "recomendacoes_clinicas": [{"title": "Diagnóstico e âmbito", "text": "Confirmar quadro clínico e excluir causas relevantes da anca e coluna. SDGT inclui várias estruturas; não equivale sempre a bursite ou a uma rotura. Ecografia/RM dirigidas pela suspeita clínica, fraqueza importante, traumatismo ou evolução atípica; não obrigatórias em todos os casos."}, {"title": "Evidência e limites", "text": "LEAP 2018: educação e exercício superiores à infiltração na melhoria global às 52 semanas, sem diferença significativa na intensidade da dor nesse momento. População com sintomas persistentes. ISHA é consenso, não valida doses ou testes universais."}, {"title": "Individualizar a prescrição", "text": "As seis opções são uma biblioteca, não seis exercícios obrigatórios. Escolher em função da irritabilidade, capacidade e objetivo. As doses são sugestões práticas, não uma dose ótima demonstrada. Não exigir zero dor, apoio unipodal de 30 segundos ou percentagem fixa de simetria para todos."}, {"title": "Tratamentos associados", "text": "Infiltração pode ser ponderada para sintomas selecionados, sem substituir gestão da carga e reabilitação. Após infiltração, respeitar as instruções do médico; a redução da dor não autoriza carga máxima. Não prescrever PRP, ondas de choque ou hormonas como rotina deste programa."}, {"title": "Reavaliação", "text": "Registar dor noturna, tarefa funcional relevante e tolerância à carga; usar PSFS/VISA-G se adequado. Reavaliar precocemente se deterioração e rever diagnóstico/adesão/dose se não houver tendência favorável. Os critérios abaixo são clínicos e individualizáveis, não limiares validados."}, {"title": "Isométricos", "text": "Não prometer analgesia imediata ou superioridade dos isométricos. Começar com esforço submáximo e tempos curtos se irritável. Supino e sentado são alternativas da mesma função; evitar dupla contabilização da carga."}], "criterios_progressao": [{"id": "p1", "texto": "Exercícios iniciais selecionados executados com controlo e sem agravamento sustentado do sono ou da manhã seguinte."}, {"id": "p2", "texto": "Levantar da cadeira e caminhar a distância útil para o doente com tolerância estável ou em melhoria."}, {"id": "p3", "texto": "Conseguir aumentar gradualmente a carga sem claudicação crescente; confirmar progressão com a equipa."}], "objetivos_serie": [{"id": "s1", "tipo": "qualitativo", "texto": "Sono, dor na manhã seguinte e tarefa funcional revistos.", "escala": "binario"}, {"id": "s2", "tipo": "qualitativo", "texto": "Movimento e dose selecionada tolerados com controlo.", "escala": "binario"}], "recommendations_scope": "411813db-6662-5598-af67-cfb2e38bc0f1:a70884fa-71d4-50d4-84b7-eec40824b092", "revisao_cientifica": "2026-10-28"}'::jsonb);
INSERT INTO public.protocol_phases (id,protocol_id,phase_order,name,anchor_kind,anchor_from,anchor_to,data) VALUES ('73be47c3-ff04-5081-ae60-be2c3a103995','411813db-6662-5598-af67-cfb2e38bc0f1',2,'Carga progressiva e controlo funcional','evolucao_clinica',NULL,NULL,'{"nota_ancora": "Progressão por evolução clínica; sem semanas fixas. Doses iniciais ajustáveis pelo prescritor.", "objetivos": [{"id": "o1", "label": "Aumentar gradualmente força e tolerância dos abdutores da anca."}, {"id": "o2", "label": "Melhorar sentar/levantar, escadas e controlo da bacia conforme necessidades."}], "permitido": ["Carga tolerada e progressiva, dentro do plano individual.", "Uso de apoio estável e redução de amplitude quando necessários."], "contraindicacoes": ["Não forçar alongamentos que cruzem a perna sobre o corpo enquanto provocarem dor lateral da anca.", "Evitar progressões bruscas, repetir testes dolorosos ou treinar com claudicação.", "Este plano não substitui restrições específicas após cirurgia, traumatismo, suspeita de fratura ou rotura aguda."], "hep": ["As seis opções não são obrigatórias. Fazer apenas a seleção e a dose prescritas.", "As doses do catálogo são pontos de partida práticos e devem ser revistas conforme resposta."], "recomendacoes": [{"title": "O seu plano", "text": "Escolha com a equipa 3–4 opções, sem obrigação de fazer as seis. Substitua variantes semelhantes em vez de acrescentar carga em todas. O apoio unipodal é uma opção de treino, não um exame obrigatório."}, {"title": "Sono e posições", "text": "Enquanto houver dor, evite apoiar diretamente a anca dolorosa. Experimente dormir de costas ou sobre o lado mais confortável, com almofada entre as coxas e os joelhos, mantendo a perna de cima apoiada."}, {"title": "Frequência e esforço", "text": "Comece com 2–3 sessões de força por semana, em dias alternados. Use resistência que permita terminar com mais 2–3 repetições possíveis e sem perder controlo. Os apoios podem ser mais curtos e assistidos."}, {"title": "Como progredir", "text": "Aumente uma variável de cada vez: repetições, resistência, amplitude ou dificuldade. Ajuste o degrau e mantenha apoio estável se necessário. Nos passos laterais, não cruze as pernas."}, {"title": "Atividade cardiovascular", "text": "Aumente a caminhada aos poucos, conforme resposta. Na bicicleta, ajuste posição e esforço ao conforto; não suba o selim automaticamente. Na natação, escolha o estilo tolerado, sem impor acessórios ou proibições universais."}, {"title": "Resposta ao exercício", "text": "Faça os movimentos com desconforto ligeiro e tolerável. Como referência inicial, procure não ultrapassar 3/10, salvo indicação individual. Reduza ou interrompa se a dor aumentar, alterar a marcha ou a técnica. A dor deve aproximar-se do habitual após a sessão, sem piorar claramente o sono ou a manhã seguinte; se continuar agravada no dia seguinte, reduza a dose e contacte a equipa."}, {"title": "Quando pedir ajuda", "text": "Procure avaliação urgente se não conseguir apoiar a perna após queda, surgir dor súbita intensa, febre com anca quente ou inchada, ou fraqueza/dormência novas. Peça reavaliação se a dor piorar de forma persistente, surgir dor profunda na virilha, ou não houver evolução apesar do plano ajustado."}], "recomendacoes_clinicas": [{"title": "Diagnóstico e âmbito", "text": "Confirmar quadro clínico e excluir causas relevantes da anca e coluna. SDGT inclui várias estruturas; não equivale sempre a bursite ou a uma rotura. Ecografia/RM dirigidas pela suspeita clínica, fraqueza importante, traumatismo ou evolução atípica; não obrigatórias em todos os casos."}, {"title": "Evidência e limites", "text": "LEAP 2018: educação e exercício superiores à infiltração na melhoria global às 52 semanas, sem diferença significativa na intensidade da dor nesse momento. População com sintomas persistentes. ISHA é consenso, não valida doses ou testes universais."}, {"title": "Individualizar a prescrição", "text": "As seis opções são uma biblioteca, não seis exercícios obrigatórios. Escolher em função da irritabilidade, capacidade e objetivo. As doses são sugestões práticas, não uma dose ótima demonstrada. Não exigir zero dor, apoio unipodal de 30 segundos ou percentagem fixa de simetria para todos."}, {"title": "Tratamentos associados", "text": "Infiltração pode ser ponderada para sintomas selecionados, sem substituir gestão da carga e reabilitação. Após infiltração, respeitar as instruções do médico; a redução da dor não autoriza carga máxima. Não prescrever PRP, ondas de choque ou hormonas como rotina deste programa."}, {"title": "Reavaliação", "text": "Registar dor noturna, tarefa funcional relevante e tolerância à carga; usar PSFS/VISA-G se adequado. Reavaliar precocemente se deterioração e rever diagnóstico/adesão/dose se não houver tendência favorável. Os critérios abaixo são clínicos e individualizáveis, não limiares validados."}], "criterios_progressao": [{"id": "p1", "texto": "Dose de força acordada tolerada em várias sessões, sem piora progressiva da dor noturna ou da função."}, {"id": "p2", "texto": "Melhoria das tarefas relevantes: caminhada, cadeira, escadas ou apoio numa perna quando necessário."}, {"id": "p3", "texto": "Controlo suficiente para a dificuldade seguinte, com adaptação da carga, altura e apoio; não avançar apenas por terem passado semanas."}], "objetivos_serie": [{"id": "s1", "tipo": "qualitativo", "texto": "Sono, dor na manhã seguinte e tarefa funcional revistos.", "escala": "binario"}, {"id": "s2", "tipo": "qualitativo", "texto": "Movimento e dose selecionada tolerados com controlo.", "escala": "binario"}], "recommendations_scope": "411813db-6662-5598-af67-cfb2e38bc0f1:73be47c3-ff04-5081-ae60-be2c3a103995", "revisao_cientifica": "2026-10-28"}'::jsonb);
INSERT INTO public.protocol_phases (id,protocol_id,phase_order,name,anchor_kind,anchor_from,anchor_to,data) VALUES ('d4c612fb-ed54-5ec1-8ba8-34ef7494e603','411813db-6662-5598-af67-cfb2e38bc0f1',3,'Capacidade funcional e regresso à atividade exigente','evolucao_clinica',NULL,NULL,'{"nota_ancora": "Progressão por evolução clínica; sem semanas fixas. Doses iniciais ajustáveis pelo prescritor.", "objetivos": [{"id": "o1", "label": "Recuperar força e resistência para trabalho, lazer ou desporto."}, {"id": "o2", "label": "Retomar cargas específicas gradualmente e manter autonomia na gestão do exercício."}], "permitido": ["Carga tolerada e progressiva, dentro do plano individual.", "Uso de apoio estável e redução de amplitude quando necessários."], "contraindicacoes": ["Não forçar alongamentos que cruzem a perna sobre o corpo enquanto provocarem dor lateral da anca.", "Evitar progressões bruscas, repetir testes dolorosos ou treinar com claudicação.", "Este plano não substitui restrições específicas após cirurgia, traumatismo, suspeita de fratura ou rotura aguda."], "hep": ["As seis opções não são obrigatórias. Fazer apenas a seleção e a dose prescritas.", "As doses do catálogo são pontos de partida práticos e devem ser revistas conforme resposta."], "recomendacoes": [{"title": "O seu plano", "text": "Faça as 3–4 opções selecionadas para o seu objetivo. Esta fase também serve tarefas exigentes do dia a dia; não exige praticar desporto. Exercícios numa perna entram apenas quando tolerados."}, {"title": "Frequência e recuperação", "text": "Faça força habitualmente 2–3 vezes por semana em dias alternados, ajustando à carga do trabalho e do treino. Aumentar a resistência não implica acrescentar exercícios à sessão."}, {"title": "Regresso à corrida e ao desporto", "text": "Reintroduza primeiro períodos curtos e tolerados do gesto. Na corrida, pode alternar marcha e corrida em plano antes de aumentar duração, velocidade e subidas. Mudanças de direção e saltos exigem preparação específica orientada; não estão automaticamente autorizados por entrar nesta fase."}, {"title": "Carga total", "text": "Conte também caminhadas longas, escadas, trabalho e treinos. Aumente uma variável de cada vez e observe a resposta até à manhã seguinte. Não existe uma percentagem semanal de aumento adequada para todos."}, {"title": "Sono e posições", "text": "Use as posições de descanso que lhe sejam confortáveis. As adaptações posturais são ajustadas aos sintomas; não precisa de evitar para sempre um movimento que já tolera."}, {"title": "Resposta ao exercício", "text": "Faça os movimentos com desconforto ligeiro e tolerável. Como referência inicial, procure não ultrapassar 3/10, salvo indicação individual. Reduza ou interrompa se a dor aumentar, alterar a marcha ou a técnica. A dor deve aproximar-se do habitual após a sessão, sem piorar claramente o sono ou a manhã seguinte; se continuar agravada no dia seguinte, reduza a dose e contacte a equipa."}, {"title": "Quando pedir ajuda", "text": "Procure avaliação urgente se não conseguir apoiar a perna após queda, surgir dor súbita intensa, febre com anca quente ou inchada, ou fraqueza/dormência novas. Peça reavaliação se a dor piorar de forma persistente, surgir dor profunda na virilha, ou não houver evolução apesar do plano ajustado."}], "recomendacoes_clinicas": [{"title": "Diagnóstico e âmbito", "text": "Confirmar quadro clínico e excluir causas relevantes da anca e coluna. SDGT inclui várias estruturas; não equivale sempre a bursite ou a uma rotura. Ecografia/RM dirigidas pela suspeita clínica, fraqueza importante, traumatismo ou evolução atípica; não obrigatórias em todos os casos."}, {"title": "Evidência e limites", "text": "LEAP 2018: educação e exercício superiores à infiltração na melhoria global às 52 semanas, sem diferença significativa na intensidade da dor nesse momento. População com sintomas persistentes. ISHA é consenso, não valida doses ou testes universais."}, {"title": "Individualizar a prescrição", "text": "As seis opções são uma biblioteca, não seis exercícios obrigatórios. Escolher em função da irritabilidade, capacidade e objetivo. As doses são sugestões práticas, não uma dose ótima demonstrada. Não exigir zero dor, apoio unipodal de 30 segundos ou percentagem fixa de simetria para todos."}, {"title": "Tratamentos associados", "text": "Infiltração pode ser ponderada para sintomas selecionados, sem substituir gestão da carga e reabilitação. Após infiltração, respeitar as instruções do médico; a redução da dor não autoriza carga máxima. Não prescrever PRP, ondas de choque ou hormonas como rotina deste programa."}, {"title": "Reavaliação", "text": "Registar dor noturna, tarefa funcional relevante e tolerância à carga; usar PSFS/VISA-G se adequado. Reavaliar precocemente se deterioração e rever diagnóstico/adesão/dose se não houver tendência favorável. Os critérios abaixo são clínicos e individualizáveis, não limiares validados."}], "criterios_progressao": [{"id": "p1", "texto": "Tarefas-alvo e exposições específicas repetidas com confiança, controlo e sem agravamento sustentado."}, {"id": "p2", "texto": "Força e capacidade avaliadas em relação ao objetivo individual; testes e comparação entre lados quando úteis, sem um limiar universal."}, {"id": "p3", "texto": "Plano de manutenção definido e conhecimento de como reduzir temporariamente a carga perante uma exacerbação."}], "objetivos_serie": [{"id": "s1", "tipo": "qualitativo", "texto": "Sono, dor na manhã seguinte e tarefa funcional revistos.", "escala": "binario"}, {"id": "s2", "tipo": "qualitativo", "texto": "Movimento e dose selecionada tolerados com controlo.", "escala": "binario"}], "recommendations_scope": "411813db-6662-5598-af67-cfb2e38bc0f1:d4c612fb-ed54-5ec1-8ba8-34ef7494e603", "revisao_cientifica": "2026-10-28"}'::jsonb);
